 configuration: {"description":"{{0}}"}
 };
 return JSON.stringify(config);
 })()"},"metadata":{"type":"String","list":false,"items":[],"use_items":false}},{"parameter-name":"inputs","metadata":{"type":"String","list":true,"items":[{"type":"String","mode":"string","value":"Use a Informative message with all data Inputs you have identified and resolved like Badge Type , Badge action & User Email in bullet format."}],"use_items":true}}],"return-value-mappings":[],"header_card_fields":[],"input_parameters_mode":"dynamic","output_parameters_mode":"dynamic","id":"dc5a52afc9c240e7b6c2556196f275c7","name":"Response","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false}],"edges":[{"type":"Edge","source_node_id":"60433aac602d41e48e785e05c3017a15","target_node_id":"dc5a52afc9c240e7b6c2556196f275c7","id":"3be0afda788349eeaeb0dfdc1188bbb1"},{"type":"Edge","source_node_id":"dc5a52afc9c240e7b6c2556196f275c7","target_node_id":"8946c83b78bd4fad9062da06a0641e1d","id":"a7d2efc8d1fc4e73a57d26a36179e57b"}],"id":"primary"}],"script_variables":[],"glide_variables":[{"type":"Reference","table":"sys_user","auto_select":false,"id":"current-user","name":"user","formatType":"text","secure":false,"sensitive":false,"aiInput":false,"list":false}],"applicability":{"type":"Applicability","mode":"script","value":"true"},"roles":[],"scope":"4c2b85dceb3f6610e4a8f1b4cad0cd2f","domain":"global","topic_type":"STANDARD","channels":[],"dialog_acts_enabled":false,"id":"5941c7f23b3f62507999faac73e45a9f","name":"Guardian Badge Operations Topic","key_phrases":[],"nlu_provider":"","nlu_model":"","nlu_model_label":"","nlu_intent":"","nlu_intent_label":"","flexible_conversation_switching":false,"autopilot_topic":false,"design_categories":[],"triggerable_by_notification":false,"description":" This Topic allows user to perform badge-related actions for individuals using their email addresses.
1. Recognize and process synonymous terms for badge types and actions.
 ** Badge Actions with Synonyms **
 -Assign (synonyms: Add, Issue, New)
 -Update (synonyms: Modify, Edit, Change)
 -Replace (synonyms: Swap, Reissue)
 -Activate (synonyms: Enable, Turn On)
 -Deactivate (synonyms: Disable, Turn Off, Suspend)
 -Remove (synonyms: Delete, Revoke, Withdraw)
 -Return (synonyms: Surrender, Hand Back)
** Badge Types with Synonyms **
 -Temporary Badge(synonyms: Visitor Badge, Guest Badge, Contractor Badge, Short-Term Badge, Day Pass)
 -Mobile Credential(synonyms: Digital Badge, Virtual Badge, Mobile Pass, Phone Credential, NFC Badge, App Credential)
 -Permanent Badge(synonyms: Employee Badge, Staff Badge, Standard Badge, Long-Term Badge, Regular Badge, Access Card)

2. Assign, update, replace, activate, deactivate, remove or return badges are Badge Actions.
3. Temporary Badge, Permanent Badge and Mobile Credential are Badge Types.
3. Identify the target user for badge actions by their provided email address.","model_type":"llm","foundational":false,"modify_confirmation_enabled":false,"context_profiles":[],"title":"Guardian Badge Operations Topic","library":false,"readOnly":false,"nluMapping":"[]"}

